export const ARTICLES: Article[] = RAW.map((a) => ({
  ...a,
  cover: LOCAL[a.slug] ?? a.cover,
}));

export const bySlug = (s: string) => ARTICLES.find((a) => a.slug === s);

/** Sector for a company name, for /companies?sector= deep links. */
export const sectorFor = (name: string): string | undefined => {
  if (!name) return undefined;
  const n = name.toLowerCase();
  const hit = (companies as { display_name?: string; name: string; sector?: string }[]).find(
    (c) => (c.display_name ?? c.name).toLowerCase() === n || c.name.toLowerCase() === n,
  );
  return hit?.sector;
};

export const initialsOf = (name: string) =>
  name
    .replace(/^Dr\.\s*/, "")
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() ?? "")
    .join("");

export const relatedTo = (a: Article, n = 3) =>
  ARTICLES.filter((x) => x.slug !== a.slug && x.category === a.category).slice(0, n);
